def solve(n):
    max_colors = 0
    # Try all possible colorings with k colors
    # But we want to maximize the number of colors.
    # The maximum number of colors can't be more than n*n.
    # Let's try k = 1, 2, 3, ..., n*n.
    # This is still a lot. Let's use backtracking.

    def backtrack(r, c, current_grid, used_colors):
        nonlocal max_colors
        if r == n:
            max_colors = max(max_colors, len(used_colors))
            return

        next_r, next_c = (r, c + 1) if c < n - 1 else (r + 1, 0)

        # Try colors already used
        for color in used_colors:
            current_grid[r][c] = color
            if is_valid_partial(current_grid, r, c):
                backtrack(next_r, next_c, current_grid, used_colors)

        # Try a new color
        new_color = max(used_colors) + 1 if used_colors else 1
        current_grid[r][c] = new_color
        if is_valid_partial(current_grid, r, c):
            backtrack(next_r, next_c, current_grid, used_colors | {new_color})

    def is_valid_partial(grid, r, c):
        if r > 0 and c > 0:
            block = [grid[r-1][c-1], grid[r][c-1], grid[r-1][c], grid[r][c]]
            if len(set(block)) == 4:
                return False
        return True

    grid = [[0]*n for _ in range(n)]
    backtrack(0, 0, grid, set())
    return max_colors

